import numpy as np
from sklearn.metrics import roc_auc_score, average_precision_score, precision_recall_curve

def roc_auc(scores, y):
    """Compute AUC-ROC. Labels are used only after predictions (R10)."""
    return float(roc_auc_score(y, scores))

def auc_pr(scores, y):
    """Primary AUC-PR via average_precision_score (ADBench convention)."""
    return float(average_precision_score(y, scores))

def auc_pr_trapezoid(scores, y):
    """Secondary AUC-PR via trapezoidal rule on precision-recall curve."""
    prec, rec, _ = precision_recall_curve(y, scores)
    # trapezoidal rule
    return float(np.trapz(prec, rec))

def summarize(values):
    """Return mean, std, min, max over a list/array of values."""
    arr = np.asarray(values, dtype=np.float64)
    return {
        'mean': float(arr.mean()),
        'std': float(arr.std()),
        'min': float(arr.min()),
        'max': float(arr.max()),
    }

def evaluate_scores(scores, y):
    """Return a dict with all metrics."""
    return {
        'auc_roc': roc_auc(scores, y),
        'auc_pr_primary': auc_pr(scores, y),
        'auc_pr_secondary': auc_pr_trapezoid(scores, y),
    }
